    <section class="rts-faq-area area-2 rts-section-gap2" data-bg-src="{{ asset(\'assets/images/faq/faq-bg.webp\') }}">
        <div class="container">
            <div class="section-inner">
                <div class="section-title-area">
                    <div class="left">
                        <p class="sub-title"><img src="{{ asset(\'assets/images/feature/icon/11.svg\') }}" alt="">FAQ</p>
                        <h2 class="h3 section-title rts-text-anime-style-1 text-transform-0">Frequently Asked <br>
                            <span>Questions</span>
                        </h2>
                    </div>
                    <div class="right">
                        <p class="desc wow fadeInUp" data-wow-delay=".2s">Find quick answers to common questions about
                            VeriFact AI's algorithms, data usage, privacy protection, and accuracy indices.</p>
                    </div>
                </div>

                <div class="rts-accordion accordion-flush wow fadeInUp" data-wow-delay=".4s" id="rts-accordion">
                    <div class="accordion-item active">
                        <div class="accordion-header" id="first">
                            <h3 class="accordion-button collapse show" data-bs-toggle="collapse"
                                data-bs-target="#item__one" aria-expanded="false" aria-controls="item__one">
                                How does VeriFact AI verify if a news claim is fake?
                            </h3>
                        </div>
                        <div id="item__one" class="accordion-collapse collapse collapse show"
                            data-bs-parent="#rts-accordion">
                            <div class="accordion-body">
                                <p class="desc">VeriFact AI processes articles using lightweight client-side Natural
                                    Language Processing (NLP). We measure capitalization density, emotional sentiment
                                    levels, punctuation usage, and match text with common conspiracy keywords to
                                    calculate credibility scores.</p>
                            </div>
                        </div>
                    </div>
                    <div class="accordion-item">
                        <div class="accordion-header" id="two">
                            <h3 class="accordion-button collapsed" data-bs-toggle="collapse" data-bs-target="#item__two"
                                aria-expanded="false" aria-controls="item__two">
                                Is my checked text sent or stored on any server?
                            </h3>
                        </div>
                        <div id="item__two" class="accordion-collapse collapse" data-bs-parent="#rts-accordion">
                            <div class="accordion-body">
                                <p class="desc">No. To ensure maximum data privacy, all verification heuristics run
                                    client-side directly within your web browser. Your inputs are never logged, tracked,
                                    or sent to external databases.</p>
                            </div>
                        </div>
                    </div>
                    <div class="accordion-item">
                        <div class="accordion-header" id="three">
                            <h3 class="accordion-button collapsed" data-bs-toggle="collapse"
                                data-bs-target="#item__three" aria-expanded="false" aria-controls="item__three">
                                Can I integrate VeriFact AI with other tools?
                            </h3>
                        </div>
                        <div id="item__three" class="accordion-collapse collapse" data-bs-parent="#rts-accordion">
                            <div class="accordion-body">
                                <p class="desc">Yes. We support integrations with Slack, browser extensions, and
                                    newsroom tools via our unified API endpoints to check social media claims directly
                                    in your daily feeds.</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </section>
